    { const char * tb_v1493 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1493; }
    { const char * tb_v1494 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1494; }
