    { const char * tb_v2822 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2822; }
    { const char * tb_v2823 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
    { const char * tb_v2826 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2826; }
    { const char * tb_v2827 = "        if (at < (unsigned long long)d->vals->len) __builtin_prefetch(d->vals->data + at * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2827; }
    { const char * tb_v2828 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2828; }
    { const char * tb_v2829 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2829; }
    { const char * tb_v2830 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2830; }
