    { const char * tb_v3092 = "TB_INL void tb_wr64(long long a, long long v, int line) { TB_TOUCH(a, 8); *(volatile uint64_t *)(uintptr_t)a = (uint64_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3092; }
