    { const char * tb_v3094 = "// new_mem(байт): новый блок, заполнен нулями; адрес — число. Может не получиться (нет памяти)\n"; *(const char * *)tb_grow(v_lines) = tb_v3094; }
    { const char * tb_v3095 = "TB_API long long tb_new_mem(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3095; }
    { const char * tb_v3096 = "    if (n <= 0) { tb_err = \"new_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3096; }
    { const char * tb_v3097 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"new_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3097; }
    { const char * tb_v3098 = "    int chk = tb_memchk();\n"; *(const char * *)tb_grow(v_lines) = tb_v3098; }
