    { const char * tb_v3118 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3118; }
    { const char * tb_v3119 = "// проверить адрес для free_mem / grow_mem; вернуть заголовок блока\n"; *(const char * *)tb_grow(v_lines) = tb_v3119; }
    { const char * tb_v3120 = "static tb_memh *tb_mem_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3120; }
    { const char * tb_v3121 = "    char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3121; }
