    { const char * tb_v3150 = "// free_mem(адрес): отдать блок; free_mem(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3150; }
    { const char * tb_v3151 = "TB_API void tb_free_mem(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3151; }
