    { const char * tb_v3177 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3177; }
    { const char * tb_v3178 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v3178; }
