    { const char * tb_v3199 = "// замок в ядре: одна команда xchg + прерывания выключены, пока замок у нас\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
    { const char * tb_v3200 = "// (так прерывание не застрянет на замке, который держит прерванная задача)\n"; *(const char * *)tb_grow(v_lines) = tb_v3200; }
    { const char * tb_v3201 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3201; }
    { const char * tb_v3202 = "    uint32_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v3202; }
    { const char * tb_v3203 = "    while (__atomic_exchange_n(l, 1, __ATOMIC_ACQUIRE)) { tb_irq_restore(f); tb_yield(); f = tb_irq_save(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3203; }
    { const char * tb_v3204 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3204; }
