    { const char * tb_v3206 = "TB_INL void tb_lock_give(int *l, unsigned long f) { __atomic_store_n(l, 0, __ATOMIC_RELEASE); tb_irq_restore((uint32_t)f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3206; }
    { const char * tb_v3207 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3207; }
    { const char * tb_v3208 = "// замок в программе: атомарный обмен; занято — сначала коротко ждём, потом уступаем ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v3208; }
    { const char * tb_v3209 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3209; }
    { const char * tb_v3210 = "    while (__atomic_exchange_n(l, 1, __ATOMIC_ACQUIRE)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3210; }
