    { const char * tb_v3223 = "// ---------- канал: очередь между потоками (channel int / text ...) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3223; }
    { const char * tb_v3224 = "// send кладёт в конец (очередь растёт, отправитель не ждёт), receive берёт из начала\n"; *(const char * *)tb_grow(v_lines) = tb_v3224; }
    { const char * tb_v3225 = "// и ждёт, пока что-то придёт. close: больше не пишут; each по каналу кончается,\n"; *(const char * *)tb_grow(v_lines) = tb_v3225; }
    { const char * tb_v3226 = "// когда он закрыт и пуст. Текст копируется: отправитель может удалить свою память.\n"; *(const char * *)tb_grow(v_lines) = tb_v3226; }
    { const char * tb_v3227 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v3227; }
