    { const char * tb_v3230 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3230; }
    { const char * tb_v3231 = "    pthread_mutex_t m; pthread_cond_t cv;\n"; *(const char * *)tb_grow(v_lines) = tb_v3231; }
    { const char * tb_v3232 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3232; }
    { const char * tb_v3233 = "    char *buf; long long cap, head, len, size; int text, closed;\n"; *(const char * *)tb_grow(v_lines) = tb_v3233; }
    { const char * tb_v3234 = "} tb_chan;\n"; *(const char * *)tb_grow(v_lines) = tb_v3234; }
    { const char * tb_v3235 = "TB_API tb_chan *tb_chan_new(long long size, int text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3235; }
    { const char * tb_v3236 = "    tb_chan *ch = tb_gc_alloc(sizeof(tb_chan));\n"; *(const char * *)tb_grow(v_lines) = tb_v3236; }
