    { const char * tb_v3238 = "    memset(ch, 0, sizeof(tb_chan));\n"; *(const char * *)tb_grow(v_lines) = tb_v3238; }
    { const char * tb_v3239 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3239; }
