    { const char * tb_v3246 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3246; }
    { const char * tb_v3247 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3247; }
    { const char * tb_v3248 = "#define TB_CH_LOCK(ch) unsigned long tb_chf = tb_lock_take(&(ch)->lk)\n"; *(const char * *)tb_grow(v_lines) = tb_v3248; }
    { const char * tb_v3249 = "#define TB_CH_UNLOCK(ch) tb_lock_give(&(ch)->lk, tb_chf)\n"; *(const char * *)tb_grow(v_lines) = tb_v3249; }
