    { const char * tb_v3252 = "#define TB_CH_UNLOCK(ch) pthread_mutex_unlock(&(ch)->m)\n"; *(const char * *)tb_grow(v_lines) = tb_v3252; }
    { const char * tb_v3253 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3253; }
    { const char * tb_v3254 = "TB_API void tb_chan_send(tb_chan *ch, const void *v, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3254; }
    { const char * tb_v3255 = "    char tmp[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v3255; }
    { const char * tb_v3256 = "    const void *src = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3256; }
    { const char * tb_v3257 = "    if (ch->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3257; }
