    { const char * tb_v3267 = "    if (ch->closed) { TB_CH_UNLOCK(ch); tb_crash(line, \"канал уже закрыт: в него больше не пишут\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3267; }
    { const char * tb_v3268 = "    if (ch->len == ch->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3268; }
    { const char * tb_v3269 = "        char *nb = tb_gc_alloc(ch->cap * 2 * ch->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3269; }
    { const char * tb_v3270 = "        if (!nb) { TB_CH_UNLOCK(ch); tb_crash(line, \"не хватило памяти\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3270; }
