    { const char * tb_v3707 = "                else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
    { const char * tb_v3708 = "                    unsigned bit = x * depth, v = (r[bit / 8] >> (8 - depth - bit % 8)) & ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3708; }
    { const char * tb_v3709 = "                    raw[k] = v; s[k] = ctype == 3 ? v : v * 255 / ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3709; }
    { const char * tb_v3710 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v3710; }
    { const char * tb_v3711 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3711; }
    { const char * tb_v3712 = "            unsigned R, G, B, A;\n"; *(const char * *)tb_grow(v_lines) = tb_v3712; }
    { const char * tb_v3713 = "            if (ctype == 3) { unsigned i = s[0] < 256 ? s[0] : 0; R = pal[i][0]; G = pal[i][1]; B = pal[i][2]; A = pal[i][3]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3713; }
    { const char * tb_v3714 = "            else if (ctype == 0 || ctype == 4) { R = G = B = s[0]; A = ctype == 4 ? s[1] : (trns && raw[0] == key[0] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3714; }
    { const char * tb_v3715 = "            else { R = s[0]; G = s[1]; B = s[2]; A = ctype == 6 ? s[3] : (trns && raw[0] == key[0] && raw[1] == key[1] && raw[2] == key[2] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3715; }
    { const char * tb_v3716 = "            px[(size_t)y * w + x] = (A << 24) | (R << 16) | (G << 8) | B;\n"; *(const char * *)tb_grow(v_lines) = tb_v3716; }
    { const char * tb_v3717 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3717; }
    { const char * tb_v3718 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3718; }
    { const char * tb_v3719 = "    free(z.out);\n"; *(const char * *)tb_grow(v_lines) = tb_v3719; }
    { const char * tb_v3720 = "    *pw = (int)w; *ph = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3720; }
    { const char * tb_v3721 = "    return px;\n"; *(const char * *)tb_grow(v_lines) = tb_v3721; }
    { const char * tb_v3722 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3722; }
    { const char * tb_v3723 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v3723; }
    { const char * tb_v3724 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v3724; }
    { const char * tb_v3725 = "TB_API tb_image *tb_imgs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3725; }
    { const char * tb_v3726 = "TB_API int tb_nimg = 0, tb_img_dirty = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3726; }
    { const char * tb_v3727 = "TB_API uint32_t *tb_imgpx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3727; }
    { const char * tb_v3728 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3728; }
    { const char * tb_v3729 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3729; }
    { const char * tb_v3730 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3730; }
    { const char * tb_v3731 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3731; }
    { const char * tb_v3732 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v3732; }
    { const char * tb_v3733 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3733; }
    { const char * tb_v3734 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3734; }
    { const char * tb_v3735 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3735; }
    { const char * tb_v3736 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3736; }
    { const char * tb_v3737 = "    uint32_t *px = tb_png(d, (size_t)sz, &w, &h, &why);\n"; *(const char * *)tb_grow(v_lines) = tb_v3737; }
    { const char * tb_v3738 = "    free(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3738; }
    { const char * tb_v3739 = "    if (!px) { tb_err = why; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3739; }
    { const char * tb_v3740 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3740; }
    { const char * tb_v3741 = "    if (need > 0xFFFFFFFFu) { free(px); tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3741; }
    { const char * tb_v3742 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3742; }
    { const char * tb_v3743 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v3743; }
    { const char * tb_v3744 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v3744; }
    { const char * tb_v3745 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v3745; }
    { const char * tb_v3746 = "    if (!all || !list) { free(px); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3746; }
    { const char * tb_v3747 = "    memcpy(tb_imgpx + tb_imgpx_n, px, (size_t)w * h * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3747; }
    { const char * tb_v3748 = "    free(px);\n"; *(const char * *)tb_grow(v_lines) = tb_v3748; }
    { const char * tb_v3749 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3749; }
    { const char * tb_v3750 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v3750; }
    { const char * tb_v3751 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3751; }
    { const char * tb_v3752 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3752; }
    { const char * tb_v3753 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3753; }
    { const char * tb_v3754 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3754; }
    { const char * tb_v3755 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3755; }
    { const char * tb_v3756 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3756; }
    { const char * tb_v3757 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v3757; }
    { const char * tb_v3758 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v3758; }
    { const char * tb_v3759 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v3759; }
    { const char * tb_v3760 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3760; }
    { const char * tb_v3761 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3761; }
    { const char * tb_v3762 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3762; }
    { const char * tb_v3763 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3763; }
    { const char * tb_v3764 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3764; }
    { const char * tb_v3765 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3765; }
    { const char * tb_v3766 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3766; }
    { const char * tb_v3767 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3767; }
    { const char * tb_v3768 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v3768; }
    { const char * tb_v3769 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v3769; }
    { const char * tb_v3770 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3770; }
    { const char * tb_v3771 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3771; }
    { const char * tb_v3772 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3772; }
    { const char * tb_v3773 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v3773; }
    { const char * tb_v3774 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3774; }
    { const char * tb_v3775 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3775; }
    { const char * tb_v3776 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3776; }
    { const char * tb_v3777 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v3777; }
    { const char * tb_v3778 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3778; }
    { const char * tb_v3779 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3779; }
    { const char * tb_v3780 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v3780; }
    { const char * tb_v3781 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v3781; }
    { const char * tb_v3782 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3782; }
    { const char * tb_v3783 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v3783; }
    { const char * tb_v3784 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3784; }
    { const char * tb_v3785 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3785; }
    { const char * tb_v3786 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3786; }
    { const char * tb_v3787 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3787; }
    { const char * tb_v3788 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3788; }
    { const char * tb_v3789 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3789; }
    { const char * tb_v3790 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v3790; }
    { const char * tb_v3791 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3791; }
    { const char * tb_v3792 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v3792; }
    { const char * tb_v3793 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3793; }
    { const char * tb_v3794 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v3794; }
    { const char * tb_v3795 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v3795; }
    { const char * tb_v3796 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3796; }
    { const char * tb_v3797 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3797; }
    { const char * tb_v3798 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v3798; }
    { const char * tb_v3799 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v3799; }
    { const char * tb_v3800 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3800; }
    { const char * tb_v3801 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v3801; }
    { const char * tb_v3802 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3802; }
    { const char * tb_v3803 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3803; }
    { const char * tb_v3804 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3804; }
    { const char * tb_v3805 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3805; }
    { const char * tb_v3806 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3806; }
    { const char * tb_v3807 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3807; }
    { const char * tb_v3808 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v3808; }
    { const char * tb_v3809 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3809; }
    { const char * tb_v3810 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v3810; }
    { const char * tb_v3811 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3811; }
    { const char * tb_v3812 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v3812; }
    { const char * tb_v3813 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3813; }
    { const char * tb_v3814 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3814; }
    { const char * tb_v3815 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3815; }
    { const char * tb_v3816 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v3816; }
    { const char * tb_v3817 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3817; }
    { const char * tb_v3818 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v3818; }
    { const char * tb_v3819 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3819; }
    { const char * tb_v3820 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v3820; }
    { const char * tb_v3821 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3821; }
    { const char * tb_v3822 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v3822; }
    { const char * tb_v3823 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3823; }
    { const char * tb_v3824 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3824; }
    { const char * tb_v3825 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3825; }
    { const char * tb_v3826 = "    if (u > 0xFFFF) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3826; }
    { const char * tb_v3827 = "    unsigned segs = tb_u16(f, c + 6) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3827; }
    { const char * tb_v3828 = "    size_t ends = c + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, ranges = deltas + 2 * segs;\n"; *(const char * *)tb_grow(v_lines) = tb_v3828; }
    { const char * tb_v3829 = "    for (unsigned i = 0; i < segs; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3829; }
    { const char * tb_v3830 = "        if (u > tb_u16(f, ends + 2 * i)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3830; }
    { const char * tb_v3831 = "        unsigned s = tb_u16(f, starts + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v3831; }
    { const char * tb_v3832 = "        if (u < s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3832; }
    { const char * tb_v3833 = "        unsigned delta = tb_u16(f, deltas + 2 * i), ro = tb_u16(f, ranges + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v3833; }
    { const char * tb_v3834 = "        if (ro == 0) return (u + delta) & 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v3834; }
    { const char * tb_v3835 = "        unsigned g = tb_u16(f, ranges + 2 * i + ro + 2 * (u - s));\n"; *(const char * *)tb_grow(v_lines) = tb_v3835; }
