    { const char * tb_v5973 = "    tb_mtl.pbuf = ((id (*)(id, SEL, unsigned long, unsigned long))objc_msgSend)(tb_mtl.dev, sel_getUid(\"newBufferWithLength:options:\"), sz, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5973; }
    { const char * tb_v5974 = "    if (!tb_mtl.pbuf) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5974; }
