    { const char * tb_v6684 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6684; }
    { const char * tb_v6685 = "TB_API void tb_gfx_events(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6685; }
    { const char * tb_v6686 = "    if (tb_gpu_on) tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6686; }
    { const char * tb_v6687 = "    else XPutImage(tb_dpy, tb_xw, tb_xgc, tb_ximg, 0, 0, 0, 0, tb_gw, tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v6687; }
    { const char * tb_v6688 = "    while (XPending(tb_dpy)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6688; }
    { const char * tb_v6689 = "        XEvent e; XNextEvent(tb_dpy, &e);\n"; *(const char * *)tb_grow(v_lines) = tb_v6689; }
    { const char * tb_v6690 = "        if (e.type == SelectionRequest) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v6690; }
    { const char * tb_v6691 = "        else if (e.type == ClientMessage && (Atom)e.xclient.data.l[0] == tb_wm_del) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6691; }
    { const char * tb_v6692 = "        else if (e.type == KeyPress || e.type == KeyRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6692; }
    { const char * tb_v6693 = "            int k = tb_x_key(XLookupKeysym(&e.xkey, 0));\n"; *(const char * *)tb_grow(v_lines) = tb_v6693; }
    { const char * tb_v6694 = "            if (k) { tb_keys[k] = e.type == KeyPress; if (tb_keys[k]) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6694; }
    { const char * tb_v6695 = "            if (e.type == KeyPress) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6695; }
    { const char * tb_v6696 = "                char buf[16]; KeySym ks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6696; }
    { const char * tb_v6697 = "                XLookupString(&e.xkey, buf, sizeof buf, &ks, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6697; }
    { const char * tb_v6698 = "                if (!(e.xkey.state & ControlMask)) tb_type_cp(tb_x_uni(ks));\n"; *(const char * *)tb_grow(v_lines) = tb_v6698; }
    { const char * tb_v6699 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6699; }
    { const char * tb_v6700 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6700; }
    { const char * tb_v6701 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6701; }
    { const char * tb_v6702 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v6702; }
    { const char * tb_v6703 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6703; }
    { const char * tb_v6704 = "            if (e.type == ButtonPress && e.xbutton.button == 5) tb_wheel_add(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6704; }
    { const char * tb_v6705 = "            tb_mx = e.xbutton.x; tb_my = e.xbutton.y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6705; }
    { const char * tb_v6706 = "        } else if (e.type == MotionNotify) { tb_mx = e.xmotion.x; tb_my = e.xmotion.y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6706; }
    { const char * tb_v6707 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6707; }
    { const char * tb_v6708 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v6708; }
    { const char * tb_v6709 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6709; }
