    { const char * tb_v6823 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v6823; }
    { const char * tb_v6824 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v6824; }
