    { const char * tb_v6869 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6869; }
    { const char * tb_v6870 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6870; }
