    { const char * tb_v7046 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7046; }
    { const char * tb_v7047 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7047; }
    { const char * tb_v7048 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7048; }
