    { const char * tb_v7054 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7054; }
    { const char * tb_v7055 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v7055; }
