    { const char * tb_v7057 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7057; }
    { const char * tb_v7058 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v7058; }
    { const char * tb_v7059 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v7059; }
    { const char * tb_v7060 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v7060; }
