    { const char * tb_v7307 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v7307; }
    { const char * tb_v7308 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v7308; }
    { const char * tb_v7309 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v7309; }
    { const char * tb_v7310 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7310; }
    { const char * tb_v7311 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7311; }
    { const char * tb_v7312 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v7312; }
    { const char * tb_v7313 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7313; }
    { const char * tb_v7314 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7314; }
    { const char * tb_v7315 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7315; }
    { const char * tb_v7316 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7316; }
    { const char * tb_v7317 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7317; }
    { const char * tb_v7318 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v7318; }
    { const char * tb_v7319 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7319; }
    { const char * tb_v7320 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7320; }
    { const char * tb_v7321 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7321; }
    { const char * tb_v7322 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7322; }
    { const char * tb_v7323 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7323; }
    { const char * tb_v7324 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7324; }
    { const char * tb_v7325 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7325; }
    { const char * tb_v7326 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7326; }
    { const char * tb_v7327 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7327; }
    { const char * tb_v7328 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7328; }
    { const char * tb_v7329 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v7329; }
    { const char * tb_v7330 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v7330; }
    { const char * tb_v7331 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7331; }
