    { const char * tb_v7388 = "            tb_grec_p[tb_gslot * TB_GR_CAP + go->ri] = go->rec;\n"; *(const char * *)tb_grow(v_lines) = tb_v7388; }
    { const char * tb_v7389 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7389; }
    { const char * tb_v7390 = "        tb_ginst *g = tb_gin ? &tb_gi[tb_gin - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7390; }
    { const char * tb_v7391 = "        if (g && g->m == 3u && g->x0 == (int32_t)go->id && g->y0 == go->cull && g->ox == t0 && g->oy == tn &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7391; }
    { const char * tb_v7392 = "            g->x1 + g->y1 == go->ri && (long long)(g->y1 + 1) * tn < 2000000000) g->y1++;   // та же сетка подряд: одним вызовом\n"; *(const char * *)tb_grow(v_lines) = tb_v7392; }
    { const char * tb_v7393 = "        else tb_gpu_add(go->id, go->cull, go->ri, 1, t0, tn, 0, 3u);\n"; *(const char * *)tb_grow(v_lines) = tb_v7393; }
    { const char * tb_v7394 = "        m->gused = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v7394; }
