    { const char * tb_v7439 = "    tb_kd(m, ix, n / 2, cen, at);\n"; *(const char * *)tb_grow(v_lines) = tb_v7439; }
    { const char * tb_v7440 = "    tb_kd(m, ix + n / 2, n - n / 2, cen, at);\n"; *(const char * *)tb_grow(v_lines) = tb_v7440; }
    { const char * tb_v7441 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7441; }
    { const char * tb_v7442 = "static void tb_sphere(const tb_mesh *m, long long t0, long long tn, double *sp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7442; }
    { const char * tb_v7443 = "    double lo[3] = { 1e300, 1e300, 1e300 }, hi[3] = { -1e300, -1e300, -1e300 }, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7443; }
    { const char * tb_v7444 = "    for (long long t = t0; t < t0 + tn; t++) for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7444; }
    { const char * tb_v7445 = "        const double *p = m->v + 3 * m->t[3 * t + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7445; }
    { const char * tb_v7446 = "        for (int k = 0; k < 3; k++) { if (p[k] < lo[k]) lo[k] = p[k]; if (p[k] > hi[k]) hi[k] = p[k]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7446; }
    { const char * tb_v7447 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7447; }
    { const char * tb_v7448 = "    for (int k = 0; k < 3; k++) { sp[k] = (lo[k] + hi[k]) / 2; r += (hi[k] - sp[k]) * (hi[k] - sp[k]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7448; }
    { const char * tb_v7449 = "    sp[3] = sqrt(r) * (1 + 1e-9) + 1e-3;\n"; *(const char * *)tb_grow(v_lines) = tb_v7449; }
    { const char * tb_v7450 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7450; }
